# Factorial function
def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

def inv(x):
    return pow(x, 1000000007 - 2, 1000000007)

def expected_lis_length():
    N = int(input())
    A = list(map(int, input().split()))
    inv_sum = sum(factorial(a - 1) * inv(factorial(a)) for a in A) % 1000000007
    expected_length = Fraction(inv_sum, factorial(sum(A)))
    return expected_length.numerator

