import fractions

N, M = map(int, input().split())
P = list(map(int, input().split()))

base = 998244353
total = sum(P)

def coin_toss(n, steps, initial):
    initial = initial % n + n  # handle modulo n case
    dp = [0] * (n + 2)
    dp[initial] = 1

    for _ in range(steps):
        new_dp = [0] * (n + 2)
        for i in range(n + 1):
            if dp[i] == 0:
                continue
            for next_i in range(n + 1):
                if next_i == i:
                    new_dp[next_i] += dp[i]
                elif next_i < i:
                    break
                else:
                    new_dp[next_i] += dp[i] * int(((next_i - i) < 0) * next_i / (next_i - i))
        dp = new_dp

    return dp[n + 1] * (total * base ** P[n] // P[n]) % base

MOD = 998244353
