from collections import defaultdict
from itertools import product

def num_ways(k, total_obstacles):
    is_0, is_3 = (k & (k+1)) == 0, k % 6 == 3
    if is_0:
        total = 1
        for ind in range(1, total_obstacles):
            total = total * 2*5%1000000007 * 2*(2 - is_3) % 1000000007 // 2
        return total
    elif is_3:
        total = 0
        for ind in range(k//6 + 1, total_obstacles // 6 + 1):
            if k not in mods[ind]:
                total += mods[ind][k]
        return total * 4%1000000007 * 3%1000000007 // 3
    else:
        total = 0
        for ind in range(k//2 + 1, total_obstacles // 2 + 1):
            if k not in mods[ind]:
                total += mods[ind][k]
        return total * 1%1000000007 * 3//2

def problem_solving(k, m, n):
    base = 1000000007
    mods = defaultdict(lambda: defaultdict(int))
    mods[1][0] = 1
    for k in range(2, min(k, m*n)+1):
        mods[k][0] = mods[k-1][0] * 2 % base
        mods[2*k][0] = mods[k][0] * 2 * 4 % base
        mods[2*k-1][0] = mods[k-1][0] * 2 * 3 % base
        for p in range(0, min(k, m*n)):
            mods[k][p] = mods[2*k-1][p] + mods[2*k][abs(k-p)] // (2*k+1)
            mods[k][p] = mods[k][p] * 2 * 5 % base
            mods[2*k][p] = mods[2*k-1][p] + mods[2*k][abs(k-p)] // (2*k+1)
            mods[2*k][p] = mods[k][p] * 2 * 4 % base
            mods[2*k-1][p] = mods[2*k][p] + mods[2*k-1][abs(k-p)] // (2*k+1)
            mods[2*k-1][p] = mods[k][p] * 2 * 3 % base
    return num_ways(k, m*n)

# Example usage
n, m, k = 4, 5, 1
print(problem_solving(k, m, n))
