        visited = [-math.inf for _ in range(m)]
        q = [(grid[0][0], 0, 0, row, checker)]
        best_k = 0
        while q:
            k, i, j, row, checker = heapq.heappop(q)
            if i == m - 1 and j == n - 1 and checker:
                return k
            for x, y in [(i + 1, j), (i, j + 1)]:
                if 0 <= x < m and 0 <= y < n and not checker[x][y]:
                    checker[x][y] = True
                    heapq.heappush(q, (max(grid[y][x], k), x, y, row, checker))
                    if x == m - 1 and y == n - 1 and checker[x][y]:
                        best_k = max(best_k, k + grid[y][x])
        return best_k if checker[m - 1][n - 1] else float('inf')

    grid = [[float('inf')] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            grid[i][j] = -grid[i][j]

