from fractions import Fraction
from itertools import product

def simulate_steps(n, m, pis):
    Qs = [1]
    for _ in range(m):
        Qs.append(sum(pis) * Fraction(Qs[-1], n))
    return Qs

def simulate_steps_and_prob(n, m, pis):
    Qs = simulate_steps(n, m, pis)
    probs = []
    for pi in pis:
        probs.append(Qs[1] * (pi * Qs[1] - Qs[0] - Qs[2]) + Qs[3])
    return [Fraction(x).limit_denominator(n + 1) for x in probs]

def simulate_steps_and_prob_with_max(n, m, pis):
    Q_minus_Qs = [1, 1]
    for i in range(2, m + 1):
        Qs = simulate_steps(n, i, pis)
        Q_minus_Qs.append(Qs[i - 1] - Qs[i - 2])
    prob = (pi * (Q_minus_Qs[0] - Q_minus_Qs[2]) / n for pi in pis)
    prob = sum(pi * q for pi, q in zip(pis, prob))
    return prob

def main():
    import sys
    if len(sys.argv) > 1 and len(sys.argv[1]) > 0:
        n = int(sys.argv[1])
    else:
        n = int(input())
    if len(sys.argv) > 2 and len(sys.argv[2]) > 0:
        m = int(sys.argv[2])
    else:
        m = int(input())

    pis = [Fraction(int(x)) for x in input().strip().split()]
    pis[0] += Fraction(1 - sum(pis), n + 1)
    pis[-1] += Fraction(sum(pis), n + 1)

    if len(sys.argv) > 3:
        max_n = int(sys.argv[3])
    else:
        max_n = int(input())

    if n <= max_n:
        print(' '.join(str(p) for p in simulate_steps_and_prob(n, m, pis) if p.denominator <= max_n + 1))
    else:
        print(' '.join(str(p) for p in simulate_steps_and_prob_with_max(n, m, pis) if p.denominator <= max_n + 1))

if __name__ == '__main__':
    main()
