from collections import defaultdict

def find_safe_spots(n, tracks):
    # Using Union-Find to manage the connections between spots
    def find(x):
        if parents[x] != x:
            parents[x] = find(parents[x])
        return parents[x]

    def union(x, y):
        parents[find(x)] = find(y)

    parents = list(range(n + 1))

    for start, end in tracks:
        union(start, end)

    # Create a graph from the parents dictionary
    graph = defaultdict(list)
    for start, end in tracks:
        graph[start].append(end)

    # Find all clusters of connected spots
    clusters = {}
    visited = set()
    for i in range(1, n + 1):
        if i not in visited:
            cluster = set()
            find(i, cluster)
            clusters[i] = len(cluster)
            for j in visited:
                if i in graph[j]:
                    parents[j] = i

    safe_spots = 0
    for i, length in clusters.items():
        if length <= 4:
            safe_spots += length

    return safe_spots

# Read input
