import sys

def find_min_max(grid):
    n, m = len(grid), len(grid[0])
    dp = [[0] * m for _ in range(n)]

    def column_major_min(row, col):
        dp[row][col] = grid[row][col]
        for i in range(col + 1, m):
            if grid[row][col] < grid[row][i]:
                dp[row][col] = min(dp[row][col], dp[row][i])
            else:
                break
        return dp[row][col]

    def row_major_min(i, col):
        dp[i][col] = grid[i][col]
        for j in range(i + 1, n):
            if grid[i][col] < grid[j][col]:
                dp[i][col] = min(dp[i][col], dp[j][col])
            else:
                break
        return dp[i][col]

    min_avg = sys.maxsize
    for col in range(1, m):
        current_min_col_major = column_major_min(0, col)
        current_min_row_major = min_avg
        for row in range(1, n):
            current_min_col_major = min(current_min_col_major, dp[row][col])
            current_min_row_major = min(current_min_row_major, row_major_min(row, col))
        min_avg = min(min_avg, max(current_min_col_major, current_min_row_major))

    return min_avg

T = int(input())
for _ in range(T):
    N, M = map(int, input().split())
    grid = [list(map(int, input().split())) for _ in range(N)]
    print(find_min_max(grid))
