def compute(num_ways, mod):
    """
    Compute the current number of ways modulo the given mod
    """
    last = [1] * num_ways
    for _ in range(1, num_ways+mod):
        last = tuple([last[i-1] + last[i] for i in range(num_ways)])
    return last[-1] % mod

