import sys

def process_input():
    n, m1, m2 = map(int, input().split())
    old_set_f, old_set_g = set(), set()
    new_set_f, new_set_g = set(), set()

    for _ in range(m1):
        x, y = map(int, input().split())
        old_set_f.add((x > 0, y > 0))

    for _ in range(m2):
        x, y = map(int, input().split())
        old_set_g.add((x > 0, y > 0))

    return old_set_f, old_set_g

def check_feasibility(fx, fy, gx, gy):
    fx.add((1, 1))
    fx.add((-1, -1))
    fy.add((1, 1))
    fy.add((-1, -1))

    for (old_f1, old_f2) in old_set_f:
        for (old_g1, old_g2) in old_set_g:
            if (old_f1, old_f2, old_g1, old_g2) in old_set_f:
                continue
            changed_set_f = new_set_f.copy()
            changed_set_f.add((1, 1))
            changed_set_f.add((-1, -1))
            f_value = 0
            g_value = 0

            f_value = (f1 + f2) % 2
            g_value = (g1 + g2) % 2

            if f_value != g_value and ((x, y, f1, f2) not in new_set_f):
                break
            changed_set_f.remove((1, 1))
            changed_set_f.remove((-1, -1))

    for (old_f1, old_f2) in old_set_f:
        for (old_g1, old_g2) in old_set_g:
            if (old_f1, old_f2, old_g1, old_g2) in old_set_f:
                continue
            changed_set_f = new_set_f.copy()
            changed_set_f.add((1, 1))
            changed_set_f.add((-1, -1))
            f_value = 0
            g_value = 0

            f_value = (f1 > f2) % 2
            g_value = (g1 < g2) % 2

            if f_value != g_value and ((x, y, f1, f2) not in new_set_f):
                break
            changed_set_f.remove((1, 1))
            changed_set_f.remove((-1, -1))

