    for _ in range(N):
        for i in range(N):
            dp[-2][i][i - 1] = 1
            for j in range(i + 1, N):
                if nums[i] <= nums[j]:
                    dp[-1][i][j] = dp[-2][i][j - 1]
                else:
                    dp[-1][i][j] = dp[-2][i + 1][j]
                if dp[-1][i][j] > 0:
                    for k in range(N, 0, -1):
                        for pre in [-1, 1]:
                            extend_prefix(nums, dp[-2][i + k][j - pre])
                            dp[-1][i + k][j - pre] = dp[-2][i][j]
    msum = [sum(dp[-1][i][-1]) - dp[-1][i][N - 1] for i in range(N)]
    s = 0
    prefix = 1
    for pred in msum[:-1]:
        s += pred * prefix
        prefix = prefix * pred % MOD
    return (prefix - 1 + s) % MOD 

