from collections import defaultdict

def detect_robot(driver_rides):
    # Create a graph from the rides
    graph = defaultdict(list)
    for i in range(len(driver_rides)):
        for j in range(1, len(driver_rides[i])):
            graph[driver_rides[i][j-1]].append(driver_rides[i][j])

    # Determine if all paths between crossroads are the same
    def dfs(start, end, path):
        if start == end:
            return True
        for neighbor in graph[start]:
            if neighbor == path[-1]:
                continue
            if dfs(neighbor, end, path + [neighbor]):
                return True
        return False

    return all(dfs(start, end, []) for end in graph for start in graph[start] for path in [start, end])

