        if not visitee[i]:
            stack = [i]
            parent = dict()
            while stack:
                number = stack.pop()
                if number == target:
                    return False
                if visitee[number + 1] is True:
                    continue
                visitee[number + 1] = True
                if graph[number] is None:
                    continue
                parent[number + 1] = number
                for neighbour in graph[number + 1]:
                    if neighbour not in parent:
