import math
from typing import List

def maxGain(n: int, ages: List[int]) -> int:
    # Counts the number of non-zero bits in each age
    dense = [0] * 16
    for age in ages:
        for r in range(math.ceil(math.log2(age))):
            dense[r] += age & 1
            age >>= 1
    # Returns True if and only if the results of the first and second bit-wise AND operations are 0
    def busyPetya(prev: int, cur: int) -> bool:
        return not prev and cur

    res = 0
    for x in range(n):
        new = ages[x] + max(a - x for a in ages if not busyPetya(x, a))
        if res < new:
            res = new
    return res
