def dfs(building, starting):
    available = building[starting]
    while available:
        dest = available.pop()
        available.update(building[dest] - {starting})
        # Add the destination into the available destinations since we did not go through this route for this DFS instance.
        building[dest].add(starting)
        starting = dest

def count_subsets_less_than(n, k):
    count = 0
    while k >= 2**count and k >= 2**(count-1):
        count += 1
    return 2**count - n

