            building[a].add(b)
            building[b].add(a)
        for starting in building:
            # dfs will only return subsequences, but here the code will convert these to actual subsets.
            dfs(building, starting)
        s = set()
        for i in range(1, n+1):
            s |= {i}
        ans = count_subsets_less_than(len(s), n)
        # generate all subsets of size `ans` that will represent routes with minimal danger.
        subsets = []
        for mask in range(2**ans):
            subset = set()
            for i in range(ans):
