from functools import lru_cache

@lru_cache(maxsize=None)
def factorial(n):
    return 1 if n == 0 else n * factorial(n - 1)

def modulo_power(base, exponent, modp):
    phi = 0
    while exponent > 0:
        if exponent % 2 == 1:
            phi = phi + base
        exponent //= 2
        base *= base
        base %= modp
    return phi % modp

@lru_cache(maxsize=None)
def fibonacci(n, modp):
    if n <= 1:
        return n
    prev, curr = 0, 1
    for _ in range(2, n + 1):
        prev, curr = curr, (prev + curr) % modp
    return curr

@lru_cache(maxsize=None)
def binomial_coefficient(n, k, modp):
    return fibonacci(n + k - 1, modp) // (fibonacci(k, modp) * fibonacci(n - k, modp) % modp) % modp

def count_ways(k: int, n: int, m: int) -> int:
    # Calculate combinations for each pair (l, r) using binomial coefficient
    combinations = -1
    modp = 1000000007
    for l, r in product(range(1, k + 1), repeat=n + m):
        clz = (r - l + 1)
        combinations *= 2
        combinations = (1000000006 - combinations + modp) % modp
        combinations -= (1000000006 - binomial_coefficient(clz, clz % 10, modp)) % modp
    return combinations

