from collections import defaultdict

def find_distance_map(sets):
    distance_map = {}

    for set_length in sets:
        if set_length not in distance_map:
            sets_to_check = [set_length - 1]
            while sets_to_check:
                current_length = sets_to_check.pop()
                if current_length in distance_map:
                    continue

                for j in range(1, current_length + 1):
                    if sets_to_check[j] - sets_to_check[j - 1] != current_length - 1:
                        sets_to_check.append(sets_to_check.pop())
                    else:
                        distance_map[current_length] = sets_to_check[j]
                        break

    first_length = min(distance_map.keys())
    return first_length, distance_map[first_length]

