        stack.put(i)
        while not stack.empty():
            current = stack.get()
            for next_spot in graph[current]:
                if seen[next_spot]:
                    return True
                seen[next_spot] = True
                stack.put(next_spot)
        dead_ends.add(current)
    return False

def min_spots_to_close(n: int, tracks: List[List[int]]) -> int:
    if is_dangerous_path(n, tracks):
        return -1
    spots_to_close = -1 * n
    visited = [False] * (n + 1)
    no_tracks_left = set()
    for sp in range(1, n + 1):
        visited[sp] = True
        count = 0
        if not seen:
            continue
        while component := set():
            component.add(sp)
            visited[sp] = True
            for neighbor in graph_spots:
                if not visited[neighbor] and neighbor not in component:
                    component.add(neighbor)
    return -1

