from math import gcd

def compute_mod(m, n):
    # Ensure division and modular operation using principle of Chinese remainder theorem
    mod_gcd = gcd(m, n)
    m = m // mod_gcd
    n = n // mod_gcd
    return m * n * pow(n, -1, mod_gcd)

MOD = 998244353

# Function to generate n-th power using modular exponentiation with reduced base
def power_mod(x, n, mod=MOD):
    if n == 0 or x == 1:
        return 1
    if n == 1:
        return x % mod
    if n % 2 == 0:
        return power_mod(x*x % mod, n//2, mod)
    else:
        return power_mod(x * power_mod(x*x % mod, (n-1)//2, mod), 1, mod)

def solve(n, m):
    P = [0] * (n + 1)
    S = [0] * (n + 1)

    # Initialize probabilities
    P[0] = 1
    S[0] = 0

    # Calculate probabilities using recursive relation
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            P[i] = (P[i] * (j - 1) + S[i - 1] * (998244352 - j)) % MOD
        S[i] = (S[i-1] * 998244352 + (S[i - 1] - S[i - 2]) * (i - 1)) % MOD

    # Adjust probabilities based on modulo operation
    for i in range(n + 1):
        P[i] = (P[i] * (998244352 - i)) % MOD

    return [compute_mod(p, m) for p in P]

