from math import gcd
from functools import reduce
from itertools import pairwise

DIRS = [(0, -1), (1, 0)]

def lcm(x, y):
    def extgcd(x, y):
        if y == 0: return (1, 0)
        g, x, y = extgcd(y, x % y)
        inv = lcm(y, x // y)
        return (inv, x, y)

    a, b = x, y
    g, x, y = extgcd(a, b)
    return ((a * g) % 1000000007, (b * g) % 1000000007)

def go(row, column, obstacles):
    return reduce(lcm, (lcm(a, b) for a, b in pairwise(obstacles[row][1:])), 1)

def solution(n, m, k):
    row = [(go(i, j, obstacles) for i in range(n)) for j in range(m)]
    mods = [go(i, j, obstacles) for j in range(1, m) for i in range(n)]

    hashfunc = lambda e: reduce(lambda z, r: z * go(r[0], r[1], obstacles) + e,
                                map(lambda r: ((e * go(r[0], r[1], obstacles) - mods) % 1000000007 // (go(r[0], r[1], obstacles) ** 2) * go(r[0] + 1, r[1], obstacles) + mods * (go(r[0] + 1, r[1], obstacles) - go(r[0], r[1], obstacles) // gcd(go(r[0], r[1], obstacles), go(r[0] + 1, r[1], obstacles))))
                                        % 1000000007, pairwise([[0, e] for e in row[j]]) 
                                ) % 1000000007
    return reduce(lambda x, y: (x + y) % 1000000007, map(hashfunc, range(n)), 0) % 1000000007

n, m, k = map(int, input().split())
