from typing import NamedTuple

def max_dowry_exchange(n, m, princesses):
    # Convert princess indeces into tuple
    princesses = tuple(task['princess'] for task in princesses)
    # Sort princesses by value
    princesses.sort()

    # Find good princess by prince
    princesses_with_friends = {}
    for i, princess in enumerate(princesses):
        confirmed_princes = set()
        for prince in princess['friends']:
            if prince not in confirmed_princes:
                princesses_with_friends[princess] = princesses[i]
                break
        else:
            continue

    # Find best allocation
    selected_princesses = []
    for princess, best_friend in princesses_with_friends.items():
        if princess in princesses and best_friend in princesses:
            selected_princesses.append(princesses.index(best_friend))

    return sum(selected_princesses)

